This sketch creates a random grid of shapes and challenges you to complete 
colouring it following the four-colour problem/proof. Fill in the colours 
by dragging and dropping to get a result where there are NO TOUCHING COLOURS
(corners don't count).

** You can't change the colour of the four starter shapes! **

Buttons are availble to show you one possible solution, toggle the palette, or
generate a new image.

Right click saves the image.

@Cartocopia 2023-06-01

For the #WCCChallenge - "Don't Touch 🚫"

P.S. I'm trying to be a "never-nester". In theory it should bake the code more readable.

*/

let xCount = 20;
let yCount = 20;
let gridSize;
let cellArray = []; // 'solved' grid
let cellArray2 = []; // working grid
let starters = [];
let palette = [
	["#264653", "#2a9d8f", "#e9c46a", "#f4a261"],
	["#f6bd60", "#f7ede2", "#f5cac3", "#84a59d"],
	["#540d6e", "#ee4266", "#ffd23f", "#3bceac"],
	["#ff550d", "#2d3502", "#5a6903", "#ffca5f"],
	["#fe5d26", "#f2c078", "#faedca", "#c1dbb3"]
];
let pPointer = 0; // index of current palette
let pCount; // palette count
let cCount; // color count in current palette
let pick = -1;
let mX = 0; // constrained mouse position
let mY = 0;
let cellX = 0; // current mouse position in cell indices
let cellY = 0;
let showMe = false; // togle to show a "solved" image
var grain; // precalculated grainy background
var grainX; // grain x offset
var grainY; // grain y offset


//===========================================================================================
function setup() {
	createCanvas(windowWidth, windowHeight);
	strokeCap(ROUND);

	pCount = palette.length;
	cCount = palette[pPointer].length;

	// Precalculate an oversized grainy background once
	grain = createImage(width, height);
	grain.loadPixels();
	for (let i = 0; i < grain.width / 2; i++) {
		for (let j = 0; j < grain.height / 2; j++) {
			grain.set(i * 2, j * 2, color(random(76, 180)));
		}
	}
	grain.updatePixels();

	//UI
	button1 = createButton('Cycle Palette...');
	button1.size(180,25);
	button1.position(width * 0.5 - 390, height * 0.02);
	button1.mousePressed(cycle);
	button2 = createButton('Show a Possible Solution');
	button2.size(180,25);
	button2.position(width * 0.5 - 190, height * 0.02);
	button2.mousePressed(toggleSolution);
	button3 = createButton('Retry...');
	button3.size(180,25);
	button3.position(width * 0.5 + 10, height * 0.02);
	button3.mousePressed(resetPattern);
	button4 = createButton('New Pattern...');
	button4.size(180,25);
	button4.position(width * 0.5 + 210, height * 0.02);
	button4.mousePressed(startmeup);


	startmeup();
}

//===========================================================================================
function draw() {
	background(100);
	updateCoords();

	//ensure starters were not overwritten by resetting them...
	for(let i=0; i<starters.length; i++) {
		flood(starters[i][0],starters[i][1],starters[i][2]);
	}

	// grid area BG
	noStroke();
	fill(255);
	rect((width - xCount * gridSize) / 2, (height - yCount * gridSize) / 2, xCount * gridSize, yCount * gridSize);

	//fill the cells
	for (let y = 0; y < yCount; y++) {
		for (let x = 0; x < xCount; x++) {
			if (showMe) {
				cellfill(x, y, cellArray);
			} else {
				cellfill(x, y, cellArray2);
			}
		}
	}

	//outline the shapes
	for (let y = 0; y < yCount; y++) {
		for (let x = 0; x < xCount; x++) {
			celloutline(x, y);
		}
	}

	addGrain();

	// if a coloured cell has been clicked on, display the picked colour
	if (pick != -1) {
		fill(palette[pPointer][pick]);
		stroke(0);
		strokeWeight(2);
		circle(mX, mY, 16);
	}
}

//===========================================================================================
function toggleSolution() {
	if (showMe) {
		showMe = false;
		button2.html('Show a Possible Solution');
	} else {
		showMe = true;
		button2.html('Back to solving...');
	}
}

//===========================================================================================
function cycle() {
	pPointer = (pPointer + 1) % pCount;
}

//===========================================================================================
function resetPattern() {
	for (let x = 0; x < xCount; x++) {
		cellArray2[x] = [];
		for (let y = 0; y < yCount; y++) {
			cellArray2[x][y] = -1;
		}
	}
}


// Initialize everything
//===========================================================================================
function startmeup() {
	gridSize = floor(0.9 * min(width / xCount, height / yCount));

	noiseSeed(millis());
	noiseDetail(4, 0.0001);
	let noiseScale = 0.09

	//initialize
	for (let x = 0; x < xCount; x++) {
		cellArray[x] = [];
		cellArray2[x] = [];
		for (let y = 0; y < yCount; y++) {
			cellArray[x][y] = 0;
			cellArray2[x][y] = -1;
		}
	}

	//fill with random rectangles
	for (let i = 0; i < 20; i++) {
		//random rectangle boundaries... intentionally extending ourside the edges to get the desired look/distribution
		let x0 = floor(random(-0.5 * xCount, xCount));
		let y0 = floor(random(-0.5 * yCount, yCount));
		let x1 = floor(random(x0 + 1, 1.5 * xCount));
		let y1 = floor(random(x0 + 1, 1.5 * xCount));
		let rc = floor(random(cCount)); // potential random colour fpr area
		for (let x = max(x0, 0); x < min(x1, xCount); x++) {
			for (let y = max(y0, 0); y < min(y1, yCount); y++) {
				 // This next line mixes up color index increment or overwrite based a exponentially based random probability.  Tuned to get the results I wanted.
				cellArray[x][y] = (random(1) < pow(i / 20, 0.1)) ? ((cellArray[x][y] + 1) % cCount) : rc;
			}
		}
	}

	//remove instances of one cell of its own color by randomly grabbing one of the surrounding colours
	for (let x = 0; x < xCount; x++) {
		for (let y = 0; y < yCount; y++) {
			let check = true;
			let options = [];
			if (x > 0) {  //not left edge
				check &= cellArray[x][y] != cellArray[x - 1][y];
				options.push(cellArray[x - 1][y]);
			}
			if (x < xCount - 1) { //not right edge 
				check &= cellArray[x][y] != cellArray[x + 1][y];
				options.push(cellArray[x + 1][y]);
			}
			if (y > 0) {  //not top edge
				check &= cellArray[x][y] != cellArray[x][y - 1];
				options.push(cellArray[x][y - 1]);
			}
			if (y < yCount - 1) { //not bottom edge
				check &= cellArray[x][y] != cellArray[x][y + 1];
				options.push(cellArray[x][y + 1]);
			}
			if (check) {
				cellArray[x][y] = random(options);
			}
		}
	}

	// clear old starters if any
	while(starters.length>0) starters.pop();

	//copy 4 starting colors zones over to the working grid
	for (i = 0; i < cCount; i++) {
		let sX = floor(random(0, xCount));
		let sY = floor(random(0, yCount));
		let _wG_1 = 0; while ((cellArray[sX][sY] != i) && ++_wG_1 < 20000) { //keep randomly looking for the next colour
			sX = floor(random(0, xCount));
			sY = floor(random(0, yCount));
		}
		starters.push([sX,sY,i]);
		flood(sX, sY, i);
	}

	grainX = floor(random(width - xCount * gridSize)); //each reset create a new grain offset
	grainY = floor(random(height - yCount * gridSize));

	background(100);
}

//overlay the rprecalculated grain image with a random offset (grainX, grainY)
//===========================================================================================
function addGrain() {
	let x0 = 0 * gridSize + (width - xCount * gridSize) / 2;
	let y0 = 0 * gridSize + (height - yCount * gridSize) / 2;
	let x1 = xCount * gridSize + (width - xCount * gridSize) / 2;
	let y1 = yCount * gridSize + (height - yCount * gridSize) / 2;

	blendMode(OVERLAY);
	image(grain, x0, y0, x1 - x0, y1 - y0, grainX, grainY, x1 - y0, y1 - y0)
	blendMode(BLEND);
}

//update the globals
//===========================================================================================
function updateCoords() {
	let x0 = 0 * gridSize + (width - xCount * gridSize) / 2;
	let y0 = 0 * gridSize + (height - yCount * gridSize) / 2;
	let x1 = xCount * gridSize + (width - xCount * gridSize) / 2;
	let y1 = yCount * gridSize + (height - yCount * gridSize) / 2;
	mX = constrain((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), x0 + 8, x1 - 8);
	mY = constrain((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), y0 + 8, y1 - 8);
	cellX = constrain(floor(((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - x0) / gridSize), 0, xCount - 1);
	cellY = constrain(floor(((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - y0) / gridSize), 0, yCount - 1);
}

//colour one cell of the specified cell array
//===========================================================================================
function cellfill(_x, _y, _arr) {
	push()
	noStroke();
	if (_arr[_x][_y] >= 0) {
		fill(color(palette[pPointer][_arr[_x][_y]]));
		let x = floor(_x * gridSize + (width - xCount * gridSize) / 2);
		let y = floor(_y * gridSize + (height - xCount * gridSize) / 2);
		rect(x, y, gridSize, gridSize);
	}
	pop();
}

//outline one cell based on cellArray.  
//===========================================================================================
function celloutline(_x, _y) {
	push();
	stroke(0);
	strokeWeight(5);
	let x = _x * gridSize + (width - xCount * gridSize) / 2;
	let y = _y * gridSize + (height - xCount * gridSize) / 2;
	if (_x == 0 || cellArray[_x][_y] != cellArray[_x - 1][_y]) {
		line(x, y, x, y + gridSize);
	}
	if (_x == xCount - 1 || cellArray[_x][_y] != cellArray[_x + 1][_y]) {
		line(x + gridSize, y, x + gridSize, y + gridSize);
	}
	if (_y == 0 || cellArray[_x][_y] != cellArray[_x][_y - 1]) {
		line(x, y, x + gridSize, y);
	}
	if (_y == yCount - 1 || cellArray[_x][_y] != cellArray[_x][_y + 1]) {
		line(x, y + gridSize, x + gridSize, y + gridSize);
	}
	pop();

	if (showMe) {
		return;
	}

	// error indicator if two touching colours
	push();
	stroke(255, 0, 0);
	strokeWeight(5);
	if (_x > 0 && cellArray[_x][_y] != cellArray[_x - 1][_y] && cellArray2[_x][_y] == cellArray2[_x - 1][_y] && cellArray2[_x][_y] != -1 && cellArray2[_x - 1][_y] != -1) {
		line(x, y, x, y + gridSize);
	}
	if (_x < xCount - 1 && cellArray[_x][_y] != cellArray[_x + 1][_y] && cellArray2[_x][_y] == cellArray2[_x + 1][_y] && cellArray2[_x][_y] != -1 && cellArray2[_x + 1][_y] != -1) {
		line(x + gridSize, y, x + gridSize, y + gridSize);
	}
	if (_y > 0 && cellArray[_x][_y] != cellArray[_x][_y - 1] && cellArray2[_x][_y] == cellArray2[_x][_y - 1] && cellArray2[_x][_y] != -1 && cellArray2[_x][_y - 1] != -1) {
		line(x, y, x + gridSize, y);
	}
	if (_x < xCount - 1 && cellArray[_x][_y] != cellArray[_x][_y + 1] && cellArray2[_x][_y] == cellArray2[_x][_y + 1] && cellArray2[_x][_y] != -1 && cellArray2[_x][_y + 1] != -1) {
		line(x, y + gridSize, x + gridSize, y + gridSize);
	}
	pop();
}

//iterative function to flood fill a shape of the cellArray2 grid by following the cellArray grid with colour index _v
//===========================================================================================
function flood(_x, _y, _v) {
	cellArray2[_x][_y] = _v;
	if (_x > 0 && cellArray[_x][_y] == cellArray[_x - 1][_y] && cellArray2[_x - 1][_y] != _v) {
		flood(_x - 1, _y, _v);
	}
	if (_y > 0 && cellArray[_x][_y] == cellArray[_x][_y - 1] && cellArray2[_x][_y - 1] != _v) {
		flood(_x, _y - 1, _v);
	}
	if (_x < xCount - 1 && cellArray[_x][_y] == cellArray[_x + 1][_y] && cellArray2[_x + 1][_y] != _v) {
		flood(_x + 1, _y, _v);
	}
	if (_y < yCount - 1 && cellArray[_x][_y] == cellArray[_x][_y + 1] && cellArray2[_x][_y + 1] != _v) {
		flood(_x, _y + 1, _v);
	}
}

//disable default right mouse click
//===========================================================================================
document.addEventListener("contextmenu", (event) => event.preventDefault(), "true")

//===========================================================================================
function mouseReleased() {
	if (pick != -1) {
		flood(cellX, cellY, pick);
		pick = -1;
	}
	return false;
}

//left click picks a colour, right click does an image capture
//===========================================================================================
let lapse = 0; // mouse timer global to debounce
function mousePressed() {
	if (millis() - lapse < 400) {
		return (false);
	}
	lapse = millis();
	if (mouseButton === RIGHT) {
		save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
	} else if (mouseButton === CENTER) {
		// nothing here
	} else {
		if (!showMe) {
		  pick = cellArray2[cellX][cellY];
		}
	}
	return (false)
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
